<?php
declare(strict_types=1);
require __DIR__.'/booking-store.php';require __DIR__.'/admin/settings-lib.php';
header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');
try{$db=booking_db();if(!settings_schema_ready($db)||setting($db,'popup_enabled','0')!=='1')throw new RuntimeException('disabled');$today=booking_today();$start=setting($db,'popup_start_date');$end=setting($db,'popup_end_date');if(($start!==''&&$today<$start)||($end!==''&&$today>$end))throw new RuntimeException('outside window');$type=setting($db,'popup_type','text');$phone=preg_replace('/\D+/','',setting($db,'venue_phone'));if(strlen($phone)===10)$phone='91'.$phone;$clickType=setting($db,'popup_click_type','none');$clickUrl=match($clickType){'enquiry'=>'contact.html#enquire','whatsapp'=>$phone?'https://wa.me/'.$phone:'','custom'=>setting($db,'popup_click_url'),default=>''};echo json_encode(['enabled'=>true,'type'=>$type,'headline'=>setting($db,'popup_headline'),'text'=>setting($db,'popup_text'),'primaryText'=>setting($db,'popup_primary_text'),'primaryUrl'=>setting($db,'popup_primary_url'),'secondaryText'=>setting($db,'popup_secondary_text'),'secondaryUrl'=>setting($db,'popup_secondary_url'),'desktopImage'=>setting($db,'popup_desktop_image'),'mobileImage'=>setting($db,'popup_mobile_image'),'clickUrl'=>$clickUrl,'cooldownHours'=>(int)setting($db,'popup_cooldown_hours','24')],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);}catch(Throwable){echo json_encode(['enabled'=>false]);}
